function cocoaJava(javaPackage: string): string {
  return `${HEADER('cocoa block (MsmCocoaBlock)', javaPackage)}
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.CocoaBlock;
import net.minecraft.world.level.block.state.BlockState;

/** A cocoa-like pod (ADR 0094 D2, D5): vanilla's three ages, hanging on a block of the {@code support} tag. */
public class ModCocoaBlock extends CocoaBlock {
    private final TagKey<Block> support;

    public ModCocoaBlock(Identifier support, Properties properties) {
        super(properties);
        this.support = TagKey.create(Registries.BLOCK, support);
    }

    @Override
    protected boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        return level.getBlockState(pos.relative(state.getValue(FACING))).is(support);
    }
}
`;
}

function bedJava(javaPackage: string): string {
  return `${HEADER('bed block (MsmBedBlock)', javaPackage)}
import net.minecraft.world.attribute.BedRule;
import net.minecraft.world.attribute.EnvironmentAttribute;
import net.minecraft.world.attribute.EnvironmentAttributes;
import net.minecraft.world.item.DyeColor;
import net.minecraft.world.level.block.BedBlock;

/** A bed (ADR 0094 D2): vanilla's bed, following the straw bed rule attribute with {@code rule: straw_bed}. */
public class ModBedBlock extends BedBlock {
    private final boolean strawRule;

    public ModBedBlock(DyeColor colour, boolean strawRule, Properties properties) {
        super(colour, properties);
        this.strawRule = strawRule;
    }

    @Override
    protected EnvironmentAttribute<BedRule> getBedEnvironmentAttribute() {
        return strawRule ? EnvironmentAttributes.STRAW_BED_RULE : super.getBedEnvironmentAttribute();
    }
}
`;
}

function scaffoldingJava(javaPackage: string): string {
  return `${HEADER('scaffolding block (MsmScaffoldingBlock)', javaPackage)}
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.item.FallingBlockEntity;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ScaffoldingBlockItem;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.ScheduledTickAccess;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.ScaffoldingBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluids;

/**
 * Scaffolding (ADR 0094 D1, D2): vanilla's states, shapes and climbing (by {@code #minecraft:climbable}), with the
 * stability rule of its own (vanilla counts only its own scaffolding): on a sturdy face distance 0, on this scaffolding
 * the distance of the one below, else one more than its nearest horizontal neighbour of this block; at 7 it falls (just
 * placed) or breaks (lost its support). The item is {@link PlacingItem}.
 */
public class ModScaffoldingBlock extends ScaffoldingBlock {
    /** Distance at which scaffolding can no longer stay. */
    public static final int MAX_DISTANCE = STABILITY_MAX_DISTANCE;

    public ModScaffoldingBlock(Properties properties) {
        super(properties);
    }

    /** The stability distance at {@code pos}, counting only this block. */
    public int distance(BlockGetter level, BlockPos pos) {
        BlockPos below = pos.below();
        BlockState under = level.getBlockState(below);
        int distance = MAX_DISTANCE;
        if (under.is(this)) {
            distance = under.getValue(DISTANCE);
        } else if (under.isFaceSturdy(level, below, Direction.UP)) {
            return 0;
        }
        for (Direction side : Direction.Plane.HORIZONTAL) {
            BlockState neighbour = level.getBlockState(pos.relative(side));
            if (neighbour.is(this)) {
                distance = Math.min(distance, neighbour.getValue(DISTANCE) + 1);
                if (distance == 1) {
                    break;
                }
            }
        }
        return distance;
    }

    private boolean bottom(BlockGetter level, BlockPos pos, int distance) {
        return distance > 0 && !level.getBlockState(pos.below()).is(this);
    }

    private BlockState withDistance(BlockState state, BlockGetter level, BlockPos pos) {
        int distance = distance(level, pos);
        return state.setValue(DISTANCE, distance).setValue(BOTTOM, bottom(level, pos, distance));
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        BlockPos pos = context.getClickedPos();
        Level level = context.getLevel();
        return withDistance(defaultBlockState(), level, pos)
                .setValue(WATERLOGGED, level.getFluidState(pos).getType() == Fluids.WATER);
    }

    @Override
    protected BlockState updateShape(BlockState state, LevelReader level, ScheduledTickAccess ticks, BlockPos pos, Direction direction,
            BlockPos neighbourPos, BlockState neighbour, RandomSource random) {
        if (state.getValue(WATERLOGGED)) {
            ticks.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }
        if (!level.isClientSide()) {
            ticks.scheduleTick(pos, this, 1);
        }
        return state;
    }

    @Override
    protected void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
        BlockState now = withDistance(state, level, pos);
        if (now.getValue(DISTANCE) == MAX_DISTANCE) {
            if (state.getValue(DISTANCE) == MAX_DISTANCE) {
                FallingBlockEntity.fall(level, pos, now);
            } else {
                level.destroyBlock(pos, true);
            }
        } else if (now != state) {
            level.setBlock(pos, now, Block.UPDATE_ALL);
        }
    }

    /** The block's item, looked up each time (vanilla's shape asks before the item is registered). */
    @Override
    public Item asItem() {
        return Item.byBlock(this);
    }

    @Override
    protected boolean canBeReplaced(BlockState state, BlockPlaceContext context) {
        return context.getItemInHand().is(asItem());
    }

    @Override
    protected boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        return distance(level, pos) < MAX_DISTANCE;
    }

    @Override
    protected ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state, boolean includeData) {
        return new ItemStack(this);
    }

    /**
     * The item: on the side of this scaffolding it places on top of the column, on the top face at the end of the row
     * the player faces; sneaking places against the clicked face; a row stops before its distance would reach
     * {@link #MAX_DISTANCE}.
     */
    public static class PlacingItem extends ScaffoldingBlockItem {
        public PlacingItem(ModScaffoldingBlock block, Item.Properties properties) {
            super(block, properties);
        }

        @Override
        public BlockPlaceContext updatePlacementContext(BlockPlaceContext context) {
            ModScaffoldingBlock block = (ModScaffoldingBlock) getBlock();
            BlockPos pos = context.getClickedPos();
            Level level = context.getLevel();
            if (!level.getBlockState(pos).is(block)) {
                return block.distance(level, pos) == MAX_DISTANCE ? null : context;
            }
            Direction direction;
            if (context.isSecondaryUseActive()) {
                direction = context.isInside() ? context.getClickedFace().getOpposite() : context.getClickedFace();
            } else {
                direction = context.getClickedFace() == Direction.UP ? context.getHorizontalDirection() : Direction.UP;
            }
            BlockPos.MutableBlockPos at = pos.mutable().move(direction);
            for (int steps = 0; steps < MAX_DISTANCE; ) {
                if (level.isOutsideBuildHeight(at)) {
                    return null;
                }
                BlockState there = level.getBlockState(at);
                if (!there.is(block)) {
                    return there.canBeReplaced(context) && block.distance(level, at) < MAX_DISTANCE
                            ? BlockPlaceContext.at(context, at.immutable(), direction) : null;
                }
                at.move(direction);
                if (direction.getAxis().isHorizontal()) {
                    steps++;
                }
            }
            return null;
        }
    }
}
`;
}
